Local Abbreviation SEGS := Ubsan.M.loaded_segments.
(* [comment removed for export] *)
#[local] Opaque RiscvSemantics.store_ok.

Section Segs.
Variable rom : word -> option byte.
#[local] Existing Instance exf_fxd | 100.

Lemma fz_small : forall (fx : FPState) regs (m : word -> option byte) (s sz : Z) (ret : word),
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  (0 <= sz <= 2)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true ->
  getr regs 2 = Z_to_bv 64 s ->
  getr regs 11 = Z_to_bv 64 sz ->
  getr regs 1 = ret ->
  ret_ok ret ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 407008) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' ret M' rom /\
      rinv [((s - 64)%Z, 64%Z)] m M' /\
      getr regs' 2 = Z_to_bv 64 s /\ getr regs' 10 = Z_to_bv 64 0 /\ getr regs' 1 = getr regs 1 /\ getr regs' 8 = getr regs 8 /\ getr regs' 9 = getr regs 9 /\
      regs_agree (fun r => In r [1; 2; 8; 9; 10; 11]%list) regs regs').
Proof.
