Lemma fz_big1 : forall (fx : FPState) regs (m : word -> option byte) (s sz dp : Z),
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  (3 <= sz < 2 ^ 64)%Z ->
  (0 <= dp < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true ->
  getr regs 2 = Z_to_bv 64 s ->
  getr regs 10 = Z_to_bv 64 dp ->
  getr regs 11 = Z_to_bv 64 sz ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 407008) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 407564) M' rom /\
      rinv [((s - 64)%Z, 64%Z)] m M' /\
      rdn SEGS M' (Z_to_bv 64 (s - 8)) 8 = Some (word_to_le_bytes 8 (getr regs 1)) /\ rdn SEGS M' (Z_to_bv 64 (s - 16)) 8 = Some (word_to_le_bytes 8 (getr regs 8)) /\
      rdn SEGS M' (Z_to_bv 64 (s - 24)) 8 = Some (word_to_le_bytes 8 (getr regs 9)) /\
      getr regs' 1 = Z_to_bv 64 407052 /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 10 = Z_to_bv 64 407148 /\ getr regs' 8 = Z_to_bv 64 sz /\ getr regs' 9 = Z_to_bv 64 dp /\
