Lemma fz_C : forall (fx : FPState) regs (m : word -> option byte) (s r : Z),
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  (0 <= r < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
  getr regs 10 = Z_to_bv 64 r ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 407104) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 450456) M' rom /\
      rinv [((s - 56)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (s - 56)) 8 = Some (Z_to_le_bytes 8 r) /\
      getr regs' 1 = Z_to_bv 64 407116 /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 10 = Z_to_bv 64 (s - 48) /\
      regs_agree (fun r => In r [1; 10]%list) regs regs').
Proof.
