Lemma fz_Z : forall (fx : FPState) regs (m : word -> option byte) (s : Z) (ret : word) (v1 v8 v9 : word),
  (4096 + 64 <= s <= 2 ^ 47)%Z ->
  ret_ok ret ->
  v1 = ret ->
  rdn SEGS m (Z_to_bv 64 (s - 8)) 8 = Some (word_to_le_bytes 8 v1) ->
  rdn SEGS m (Z_to_bv 64 (s - 16)) 8 = Some (word_to_le_bytes 8 v8) ->
  rdn SEGS m (Z_to_bv 64 (s - 24)) 8 = Some (word_to_le_bytes 8 v9) ->
  getr regs 2 = Z_to_bv 64 (s - 64) ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 407124) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' ret M' rom /\
      M' = m /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 10 = Z_to_bv 64 0 /\ getr regs' 8 = v8 /\ getr regs' 9 = v9 /\
      regs_agree (fun r => In r [1; 2; 8; 9; 10]%list) regs regs').
Proof.
